var root=document.documentElement,savedTheme=localStorage.getItem("theme"),prefersDark=window.matchMedia("(prefers-color-scheme: dark)").matches;root.setAttribute("data-theme",savedTheme||(prefersDark?"dark":"light")),document.addEventListener("DOMContentLoaded",function(){document.querySelector(".theme-toggle").addEventListener("click",function(){var e="dark"===root.getAttribute("data-theme")?"light":"dark";root.setAttribute("data-theme",e),localStorage.setItem("theme",e)})});